import { test, expect } from '@playwright/test';

test.describe('Search Suggestions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display recent search terms as suggestions', async ({ page }) => {
    await page.fill('input[name="search"]', 'Playwright');
    await page.press('input[name="search"]', 'Enter');

    await page.fill('input[name="search"]', 'Playwright');
    await expect(page.getByRole('listbox')).toBeVisible();
    await expect(page.getByText('Playwright')).toBeVisible();
  });

  test('should show different suggestions for different searches', async ({ page }) => {
    await page.fill('input[name="search"]', 'Cypress');
    await page.press('input[name="search"]', 'Enter');

    await page.fill('input[name="search"]', 'Cypress');
    await expect(page.getByRole('listbox')).toBeVisible();
    await expect(page.getByText('Cypress')).toBeVisible();
    await expect(page.getByText('Playwright')).not.toBeVisible();
  });
});
